class Solution:
    def calDis(self, origin: tuple[int], destination: tuple[int]) -> int:
        return abs(origin[0] - destination[0]) + abs(origin[1] - destination[1])

    def maxDistance(self, grid: list[list[int]]) -> int:
        n = len(grid)
        DIRS = [(-1, 0), (0, -1), (1, 0), (0, 1), ]
        queue = deque()

        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    queue.append((i, j))

        if len(queue) == 0 or len(queue) == n**2:
            return -1

        best = 0
        while queue:
            k = len(queue)
            for _ in range(k):
                r, c = queue.popleft()
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 0:
                        grid[nr][nc] = self.calDis((r, c), (nr, nc)) + grid[r][c]
                        best = max(best, grid[nr][nc])
                        queue.append((nr, nc))

        return best - 1
